script:
// ---- full page width -------------------------------------------------
// Removes the workspace's max-width so the dashboard fills the screen,
// and puts it back when you navigate to any other page.
(function () {
  var W = (window.__tbhSD = window.__tbhSD || { saved: [], hooked: false });
  function onPage() { return /\/solar-dashboard\/?$/i.test(location.pathname); }
  function restore() { W.saved.forEach(function (p) { p[0].style.maxWidth = p[1]; }); W.saved = []; }
  function widen() {
    restore();
    if (!onPage()) { return; }
    var rn = root_element.getRootNode ? root_element.getRootNode() : null;
    var el = (rn && rn.host) || root_element;
    while (el && el !== document.body && el !== document.documentElement) {
      var mw = getComputedStyle(el).maxWidth;
      if (mw && mw !== 'none') { W.saved.push([el, el.style.maxWidth]); el.style.maxWidth = 'none'; }
      el = el.parentElement;
    }
  }
  W.apply = widen;
  if (!W.hooked && frappe.router && typeof frappe.router.on === 'function') {
    W.hooked = true;
    frappe.router.on('change', function () { setTimeout(function () { if (W.apply) { W.apply(); } }, 60); });
  }
  widen();
  setTimeout(widen, 300);
})();

// Fixed rows: core doctypes whose status lists are too long to show in full.
const FIXED = [
  { title: 'Leads', dt: 'Lead', color: '#2563eb', rows: [
    { label: 'Lead', f: { status: 'Lead' } },
    { label: 'Open', f: { status: 'Open' } },
    { label: 'Replied', f: { status: 'Replied' } },
    { label: 'Converted', f: { status: 'Converted' } }
  ]},
  { title: 'Quotation', dt: 'Quotation', color: '#7c3aed', rows: [
    { label: 'Draft', f: { status: 'Draft' } },
    { label: 'Open', f: { status: 'Open' } },
    { label: 'Ordered', f: { status: 'Ordered' } },
    { label: 'Lost', f: { status: 'Lost' } }
  ]},
  { title: 'Sales Order', dt: 'Sales Order', color: '#0891b2', rows: [
    { label: 'To Deliver and Bill', f: { status: 'To Deliver and Bill' } },
    { label: 'To Deliver', f: { status: 'To Deliver' } },
    { label: 'To Bill', f: { status: 'To Bill' } },
    { label: 'Completed', f: { status: 'Completed' } }
  ]},
  { title: 'Sales Invoice', dt: 'Sales Invoice', color: '#059669', rows: [
    { label: 'Draft', f: { status: 'Draft' } },
    { label: 'Unpaid', f: { status: 'Unpaid' } },
    { label: 'Overdue', f: { status: 'Overdue' } },
    { label: 'Paid', f: { status: 'Paid' } },
    { label: 'Return', f: { status: 'Return' } }
  ]}
];

const AUTO = [
  { title: 'Loan',               dt: 'Solar Loan',         field: 'status',                     color: '#4f46e5' },
  { title: 'Site Visit',         dt: 'Site Visit',         field: 'status',                     color: '#0d9488' },
  { title: 'Project',            dt: 'Project',            field: 'status',                     color: '#db2777' },
  { title: 'Product Delivery',   dt: 'Product Delivery',   field: 'transfer_status',            color: '#ea580c' },
  { title: 'Installation',       dt: 'Installation',       field: 'installation_status',        color: '#16a34a' },
  { title: 'Paper Work',         dt: 'Paper Work',         field: 'status',                     color: '#0284c7' },
  { title: 'Subsidy',            dt: 'Subsidy',            field: 'status',                     color: '#d97706' },
  { title: 'KSEB',               dt: 'KSEB Paper Works',   field: 'status_of_kseb_paper_work',  color: '#0f766e' },
  { title: 'Project Commission', dt: 'Project Commission', field: 'status_of_project_commission', color: '#9333ea' }
];

const TREND = [
  { name: 'Lead',          dt: 'Lead',          datefield: 'creation',         color: '#2563eb' },
  { name: 'Quotation',     dt: 'Quotation',     datefield: 'transaction_date', color: '#7c3aed' },
  { name: 'Sales Order',   dt: 'Sales Order',   datefield: 'transaction_date', color: '#0891b2' },
  { name: 'Sales Invoice', dt: 'Sales Invoice', datefield: 'posting_date',     color: '#059669' }
];

const MONTHS_BACK = 12;
const GL_ROW_CAP = 20000;

const grid = root_element.querySelector('.sd-grid');
const chartBox = root_element.querySelector('.sd-chart');
const plBox = root_element.querySelector('.sd-chart-pl');

function tone_for(label) {
  const l = String(label).toLowerCase();
  if (l.indexOf('cancel') > -1 || l.indexOf('lost') > -1 || l.indexOf('reject') > -1 || l.indexOf('fail') > -1 || l.indexOf('overdue') > -1) { return 'bad'; }
  if (l.indexOf('complet') > -1 || l.indexOf('approv') > -1 || l.indexOf('sanction') > -1 || l.indexOf('transferr') > -1 || l.indexOf('visited') > -1 || l.indexOf('commission') > -1 || l.indexOf('disburs') > -1 || l.indexOf('paid') > -1) { return 'good'; }
  if (l.indexOf('progress') > -1 || l.indexOf('process') > -1 || l.indexOf('review') > -1 || l.indexOf('submit') > -1) { return 'info'; }
  if (l.indexOf('pending') > -1 || l.indexOf('not ') > -1 || l.indexOf('applied') > -1 || l.indexOf('hold') > -1 || l.indexOf('unpaid') > -1) { return 'warn'; }
  return 'idle';
}

function count(dt, filters) {
  return frappe.db.count(dt, filters ? { filters: filters } : undefined)
    .then(function(v) { return v || 0; })
    .catch(function() { return 0; });
}

function status_options(dt, fieldname) {
  return new Promise(function(resolve) {
    frappe.model.with_doctype(dt, function() {
      var df = null;
      try { df = frappe.meta.get_docfield(dt, fieldname); } catch (e) { df = null; }
      if (!df || !df.options) { resolve([]); return; }
      resolve(String(df.options).split('\n').map(function(s) { return s.trim(); }).filter(function(s) { return s.length; }));
    });
  });
}

function shell(card, container) {
  const el = document.createElement('div');
  el.className = 'sd-card';
  el.style.setProperty('--accent', card.color);
  el.innerHTML = '<div class="sd-card-head">' + card.title + '</div>' +
    '<div class="sd-rows"></div>' +
    '<div class="sd-total"><span>Total</span><span class="sd-tval">–</span></div>';
  container.appendChild(el);
  return el;
}

function paint_rows(el, card, rows) {
  const holder = el.querySelector('.sd-rows');
  if (!rows.length) {
    holder.innerHTML = '<div class="sd-empty">No status options found</div>';
  } else {
    holder.innerHTML = rows.map(function(r, i) {
      return '<div class="sd-row" data-i="' + i + '">' +
             '<span class="sd-dot sd-dot-' + tone_for(r.label) + '"></span>' +
             '<span class="sd-label">' + r.label + '</span>' +
             '<span class="sd-val">–</span></div>';
    }).join('');
    const rowEls = holder.querySelectorAll('.sd-row');
    rows.forEach(function(r, i) {
      rowEls[i].addEventListener('click', function() { frappe.set_route('List', card.dt, r.f); });
      count(card.dt, r.f).then(function(v) {
        rowEls[i].querySelector('.sd-val').textContent = v;
        if (!v) { rowEls[i].classList.add('sd-zero'); }
      });
    });
  }
  el.querySelector('.sd-total').addEventListener('click', function() { frappe.set_route('List', card.dt); });
  count(card.dt).then(function(v) { el.querySelector('.sd-tval').textContent = v; });
}

FIXED.forEach(function(card) {
  paint_rows(shell(card, grid), card, card.rows);
});

AUTO.forEach(function(card) {
  const el = shell(card, grid);
  el.querySelector('.sd-rows').innerHTML = '<div class="sd-empty">Loading…</div>';
  status_options(card.dt, card.field).then(function(opts) {
    paint_rows(el, card, opts.map(function(o) {
      var f = {}; f[card.field] = o;
      return { label: o, f: f };
    }));
  });
});

// ---- shared month axis ------------------------------------------------
// Rows are fetched as plain values and bucketed by month in the browser.
// Grouping with SQL date functions is rejected by Frappe field validation,
// so this stays on a path that is always permitted.

function month_axis(n) {
  var keys = [], labels = [];
  var now = new Date();
  for (var i = n - 1; i >= 0; i--) {
    var t = new Date(now.getFullYear(), now.getMonth() - i, 1);
    keys.push(t.getFullYear() + '-' + ('0' + (t.getMonth() + 1)).slice(-2));
    labels.push(t.toLocaleString('en', { month: 'short' }) + ' ' + String(t.getFullYear()).slice(-2));
  }
  return { keys: keys, labels: labels };
}

const AXIS = month_axis(MONTHS_BACK);
const START = AXIS.keys[0] + '-01';

function month_series(cfg) {
  var filters = {};
  filters[cfg.datefield] = ['>=', START];

  return frappe.db.get_list(cfg.dt, {
    fields: [cfg.datefield],
    filters: filters,
    order_by: cfg.datefield + ' asc',
    limit: 5000
  }).then(function(rows) {
    var buckets = {};
    AXIS.keys.forEach(function(k) { buckets[k] = 0; });
    (rows || []).forEach(function(r) {
      var v = r[cfg.datefield];
      if (!v) { return; }
      var k = String(v).slice(0, 7);
      if (buckets[k] !== undefined) { buckets[k] += 1; }
    });
    return AXIS.keys.map(function(k) { return buckets[k]; });
  }).catch(function() {
    return AXIS.keys.map(function() { return 0; });
  });
}

function draw_trend() {
  if (typeof frappe.Chart === 'undefined') {
    chartBox.innerHTML = '<div class="sd-chart-empty">Chart library not available on this page.</div>';
    return;
  }

  chartBox.innerHTML = '<div class="sd-chart-empty">Loading trend…</div>';

  Promise.all(TREND.map(month_series)).then(function(all) {
    var grand = all.reduce(function(a, s) {
      return a + s.reduce(function(x, y) { return x + y; }, 0);
    }, 0);

    if (!grand) {
      chartBox.innerHTML = '<div class="sd-chart-empty">No documents in the last ' + MONTHS_BACK + ' months.</div>';
      return;
    }

    chartBox.innerHTML = '';
    new frappe.Chart(chartBox, {
      type: 'bar',
      height: 290,
      colors: TREND.map(function(t) { return t.color; }),
      data: {
        labels: AXIS.labels,
        datasets: TREND.map(function(t, i) {
          return { name: t.name, values: all[i] };
        })
      },
      barOptions: { spaceRatio: 0.4 },
      axisOptions: { xIsSeries: 1 }
    });
  }).catch(function() {
    chartBox.innerHTML = '<div class="sd-chart-empty">Could not load the trend data.</div>';
  });
}

// ---- profit and loss --------------------------------------------------
// Income and expense are summed from posted GL Entries so the figures match
// the ledger rather than being inferred from invoice totals. Root type lives
// on Account, not GL Entry, so the income and expense accounts are resolved
// first and used as a filter.
//
// All three series are bars. shortenYAxisNumbers keeps large rupee figures
// readable on the axis instead of printing every digit.

function draw_pl() {
  if (typeof frappe.Chart === 'undefined') {
    plBox.innerHTML = '<div class="sd-chart-empty">Chart library not available on this page.</div>';
    return;
  }

  plBox.innerHTML = '<div class="sd-chart-empty">Loading profit and loss…</div>';

  frappe.db.get_list('Account', {
    fields: ['name', 'root_type'],
    filters: { root_type: ['in', ['Income', 'Expense']] },
    limit: 1000
  }).then(function(accounts) {
    if (!accounts || !accounts.length) {
      plBox.innerHTML = '<div class="sd-chart-empty">No income or expense accounts found.</div>';
      return;
    }

    var type_of = {};
    var names = [];
    accounts.forEach(function(a) { type_of[a.name] = a.root_type; names.push(a.name); });

    return frappe.db.get_list('GL Entry', {
      fields: ['posting_date', 'account', 'debit', 'credit'],
      filters: {
        posting_date: ['>=', START],
        is_cancelled: 0,
        account: ['in', names]
      },
      order_by: 'posting_date asc',
      limit: GL_ROW_CAP
    }).then(function(rows) {
      var inc = {}, exp = {};
      AXIS.keys.forEach(function(k) { inc[k] = 0; exp[k] = 0; });

      (rows || []).forEach(function(g) {
        var k = String(g.posting_date || '').slice(0, 7);
        if (inc[k] === undefined) { return; }
        var t = type_of[g.account];
        if (t === 'Income') {
          inc[k] += flt(g.credit) - flt(g.debit);
        } else if (t === 'Expense') {
          exp[k] += flt(g.debit) - flt(g.credit);
        }
      });

      var income  = AXIS.keys.map(function(k) { return Math.round(inc[k]); });
      var expense = AXIS.keys.map(function(k) { return Math.round(exp[k]); });
      var profit  = AXIS.keys.map(function(k) { return Math.round(inc[k] - exp[k]); });

      var any = income.concat(expense).some(function(v) { return v !== 0; });
      if (!any) {
        plBox.innerHTML = '<div class="sd-chart-empty">No posted income or expense in the last ' + MONTHS_BACK + ' months.</div>';
        return;
      }

      plBox.innerHTML = '';
      new frappe.Chart(plBox, {
        type: 'bar',
        height: 290,
        colors: ['#16a34a', '#dc2626', '#2563eb'],
        data: {
          labels: AXIS.labels,
          datasets: [
            { name: 'Income', values: income },
            { name: 'Expense', values: expense },
            { name: 'Net Profit', values: profit }
          ]
        },
        barOptions: { spaceRatio: 0.4 },
        axisOptions: { xIsSeries: 1, shortenYAxisNumbers: 1 }
      });
    });
  }).catch(function() {
    plBox.innerHTML = '<div class="sd-chart-empty">Could not load ledger data. This needs read access to Account and GL Entry.</div>';
  });
}

draw_trend();
draw_pl();

style:
:host { display: block; }
.sd-wrap { padding: 2px 0 8px; width: 100%; }
.sd-head { margin-bottom: 18px; }
.sd-title { font-size: 21px; font-weight: 600; letter-spacing: -0.01em; }
.sd-sub { font-size: 12px; color: var(--text-muted, #6b7280); margin-top: 3px; }

.sd-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(255px, 1fr)); gap: 14px; }

.sd-card { background: var(--card-bg, #fff); border: 1px solid var(--border-color, #e5e7eb); border-radius: 12px; padding: 15px 16px 12px; display: flex; flex-direction: column; position: relative; overflow: hidden; }
.sd-card::before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 3px; background: var(--accent); }

.sd-card-head { font-size: 14px; font-weight: 600; color: var(--accent); margin-bottom: 12px; }

.sd-rows { flex: 1; }
.sd-row { display: flex; align-items: center; gap: 8px; padding: 6px 6px; margin: 0 -6px; font-size: 13px; cursor: pointer; border-radius: 6px; transition: background 0.12s ease; }
.sd-row:hover { background: var(--fg-hover-color, #f3f4f6); }
.sd-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--accent); flex: none; }
.sd-dot-good { background: #16a34a; }
.sd-dot-warn { background: #ea580c; }
.sd-dot-info { background: #2563eb; }
.sd-dot-bad { background: #dc2626; }
.sd-dot-idle { background: #9ca3af; }
.sd-label { color: var(--text-color, #374151); flex: 1; }
.sd-val { font-weight: 600; font-variant-numeric: tabular-nums; }
.sd-zero .sd-label, .sd-zero .sd-val { color: var(--text-muted, #9ca3af); }
.sd-zero .sd-dot { opacity: 0.35; }
.sd-empty { font-size: 12px; color: var(--text-muted, #9ca3af); padding: 6px 0; }

.sd-total { display: flex; justify-content: space-between; align-items: baseline; margin-top: 10px; padding-top: 10px; border-top: 1px solid var(--border-color, #e5e7eb); font-size: 12px; font-weight: 600; color: var(--text-muted, #6b7280); cursor: pointer; }
.sd-tval { font-size: 19px; font-weight: 700; color: var(--accent); font-variant-numeric: tabular-nums; }

/* section break */
.sd-divider { height: 1px; background: var(--border-color, #e5e7eb); margin: 28px 0 18px; }
.sd-section-head { font-size: 16px; font-weight: 600; letter-spacing: -0.01em; }
.sd-section-sub { font-size: 12px; color: var(--text-muted, #6b7280); margin-top: 3px; margin-bottom: 14px; }

/* trend chart */
.sd-chart-card { --accent: #2563eb; padding: 6px 10px 2px; }
.sd-chart-empty { font-size: 12px; color: var(--text-muted, #9ca3af); padding: 28px 6px; text-align: center; }
.sd-chart .chart-legend { font-size: 12px; }

script:
const ICONS = {
  issue:  '<circle cx="12" cy="12" r="9"/><path d="M9.6 9.4a2.5 2.5 0 1 1 3.3 2.4c-.6.2-.9.7-.9 1.3v.4"/><path d="M12 16.8h.01"/>',
  clock:  '<circle cx="12" cy="12" r="9"/><path d="M12 7.2V12l3 1.9"/>',
  tag:    '<path d="M20.6 13.4 12 22l-9-9V3h10z"/><circle cx="7.6" cy="7.6" r="1.1"/>',
  calendar: '<rect x="3" y="4.5" width="18" height="16.5" rx="2.5"/><path d="M3 10h18M8 2.5v4M16 2.5v4"/>',
  clipboard: '<rect x="4" y="4" width="16" height="17" rx="2.5"/><path d="M9 2.5h6v4H9z"/><path d="M8.6 13.4l2.4 2.4 4.4-4.6"/>',
  gear:   '<circle cx="12" cy="12" r="3.1"/><path d="M12 2.2v2.6M12 19.2v2.6M2.2 12h2.6M19.2 12h2.6M5.4 5.4l1.9 1.9M16.7 16.7l1.9 1.9M18.6 5.4l-1.9 1.9M7.3 16.7l-1.9 1.9"/>',
  check:  '<circle cx="12" cy="12" r="9"/><path d="M8.4 12.4l2.5 2.5 4.6-5"/>',
  shield: '<path d="M12 2.8l7 2.9v5.9c0 4.5-3 7.7-7 9.1-4-1.4-7-4.6-7-9.1V5.7z"/>',
  shieldcheck: '<path d="M12 2.8l7 2.9v5.9c0 4.5-3 7.7-7 9.1-4-1.4-7-4.6-7-9.1V5.7z"/><path d="M9.1 11.9l2 2 3.8-4"/>',
  doc:    '<path d="M14 2.8H7a2 2 0 0 0-2 2v14.4a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V7.8z"/><path d="M14 2.8v5h5M9 13.2h6M9 16.8h4"/>',
  flag:   '<path d="M5.2 21.2V3.6h13l-2.6 4.2 2.6 4.2H5.2"/>'
};

function svg(k) {
  return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">' + (ICONS[k] || '') + '</svg>';
}

// ---- Headline figures -------------------------------------------------
const KPIS = [
  { label: 'Open Issues',          dt: 'Issue',             f: { status: 'Open' },                          tone: 'warn', icon: 'issue' },
  { label: 'SLA Failed',           dt: 'Issue',             f: { agreement_status: 'Failed' },               tone: 'bad',  icon: 'clock' },
  { label: 'Open Warranty Claims', dt: 'Warranty Claim',    f: { status: 'Open' },                           tone: 'info', icon: 'shield' },
  { label: 'Visits Part. Done',    dt: 'Maintenance Visit', f: { completion_status: 'Partially Completed' }, tone: 'good', icon: 'clipboard' }
];

// ---- Check-box driven card (options can't be read from a Select) ------
const FIXED = [
  { title: 'Service Level Agreement', sub: 'Service Level Agreement', icon: 'doc', color: '#0f766e', dt: 'Service Level Agreement', rows: [
    { label: 'Enabled', f: { enabled: 1 } },
    { label: 'Disabled', f: { enabled: 0 } },
    { label: 'Default SLA', f: { default_service_level_agreement: 1 } },
    { label: 'Applies to Resolution', f: { apply_sla_for_resolution: 1 } }
  ]}
];

// ---- Select-field cards: options read live from the DocType ----------
const AUTO = [
  { title: 'Issues',               sub: 'Issue',                icon: 'issue',       dt: 'Issue',                field: 'status',              color: '#2563eb' },
  { title: 'SLA Status',           sub: 'Issue',                icon: 'clock',       dt: 'Issue',                field: 'agreement_status',    color: '#dc2626' },
  { title: 'Maintenance Schedule', sub: 'Maintenance Schedule', icon: 'calendar',    dt: 'Maintenance Schedule', field: 'status',              color: '#0d9488' },
  { title: 'Maintenance Visit',    sub: 'Maintenance Visit',    icon: 'clipboard',   dt: 'Maintenance Visit',    field: 'status',              color: '#ea580c' },
  { title: 'Maintenance Type',     sub: 'Maintenance Visit',    icon: 'gear',        dt: 'Maintenance Visit',    field: 'maintenance_type',    color: '#7c3aed' },
  { title: 'Visit Completion',     sub: 'Maintenance Visit',    icon: 'check',       dt: 'Maintenance Visit',    field: 'completion_status',   color: '#0891b2' },
  { title: 'Warranty Claim',       sub: 'Warranty Claim',       icon: 'shield',      dt: 'Warranty Claim',       field: 'status',              color: '#16a34a' },
  { title: 'Warranty / AMC',       sub: 'Warranty Claim',       icon: 'shieldcheck', dt: 'Warranty Claim',       field: 'warranty_amc_status', color: '#d97706' }
];

// ---- Link-field cards: rows read live from the master doctype --------
const LINKED = [
  { title: 'Issues by Type', sub: 'Issue Type', icon: 'tag', dt: 'Issue', field: 'issue_type', master: 'Issue Type', color: '#4f46e5' }
];

const WIDE = { title: 'Issues by Priority', sub: 'Issue Priority', icon: 'flag', dt: 'Issue', field: 'priority', master: 'Issue Priority', color: '#9333ea' };

const kpiBox = root_element.querySelector('.sdx-kpis');
const grid   = root_element.querySelector('.sdx-grid');
const wide   = root_element.querySelector('.sdx-wide');

function tone_for(label) {
  const l = String(label).toLowerCase().trim();
  if (l === 'low') { return 'good'; }
  if (l === 'medium') { return 'info'; }
  if (l === 'high') { return 'warn'; }
  if (l === 'urgent' || l === 'critical') { return 'bad'; }
  if (l.indexOf('partial') > -1 || l.indexOf('unschedul') > -1) { return 'warn'; }
  if (l.indexOf('out of') > -1 || l.indexOf('cancel') > -1 || l.indexOf('reject') > -1 || l.indexOf('fail') > -1 || l.indexOf('breakdown') > -1 || l.indexOf('disabled') > -1) { return 'bad'; }
  if (l.indexOf('complet') > -1 || l.indexOf('resolv') > -1 || l.indexOf('closed') > -1 || l.indexOf('fulfill') > -1 || l.indexOf('under ') > -1 || l.indexOf('enabled') > -1) { return 'good'; }
  if (l.indexOf('progress') > -1 || l.indexOf('replied') > -1 || l.indexOf('submitted') > -1 || l.indexOf('schedul') > -1 || l.indexOf('default') > -1) { return 'info'; }
  if (l.indexOf('open') > -1 || l.indexOf('hold') > -1 || l.indexOf('due') > -1 || l.indexOf('pending') > -1 || l.indexOf('applies') > -1) { return 'warn'; }
  return 'idle';
}

function count(dt, filters) {
  return frappe.db.count(dt, filters ? { filters: filters } : undefined)
    .then(function(v) { return v || 0; })
    .catch(function() { return 0; });
}

function status_options(dt, fieldname) {
  return new Promise(function(resolve) {
    frappe.model.with_doctype(dt, function() {
      var df = null;
      try { df = frappe.meta.get_docfield(dt, fieldname); } catch (e) { df = null; }
      if (!df || !df.options) { resolve([]); return; }
      resolve(String(df.options).split('\n').map(function(s) { return s.trim(); }).filter(function(s) { return s.length; }));
    });
  });
}

function link_options(master) {
  return frappe.db.get_list(master, { fields: ['name'], limit: 40, order_by: 'name asc' })
    .then(function(rows) { return (rows || []).map(function(r) { return r.name; }); })
    .catch(function() { return []; });
}

function to_rows(field, opts) {
  return opts.map(function(o) {
    var f = {}; f[field] = o;
    return { label: o, f: f };
  });
}

function esc(s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }

// ---- KPI strip --------------------------------------------------------
function paint_kpis() {
  kpiBox.innerHTML = KPIS.map(function(k) {
    return '<div class="sdx-kpi t-' + k.tone + '">' +
           '<div class="sdx-kpi-ico">' + svg(k.icon) + '</div>' +
           '<div class="sdx-kpi-body"><div class="sdx-kpi-val">\u00b7\u00b7</div>' +
           '<div class="sdx-kpi-lbl">' + esc(k.label) + '</div></div></div>';
  }).join('');
  const els = kpiBox.querySelectorAll('.sdx-kpi');
  KPIS.forEach(function(k, i) {
    els[i].addEventListener('click', function() { frappe.set_route('List', k.dt, k.f); });
    count(k.dt, k.f).then(function(v) {
      els[i].querySelector('.sdx-kpi-val').textContent = v;
      if (!v) { els[i].classList.add('is-zero'); }
    });
  });
}

// ---- Card shell -------------------------------------------------------
function shell(card, container) {
  const el = document.createElement('div');
  el.className = 'sdx-card';
  el.style.setProperty('--accent', card.color);
  el.innerHTML =
    '<div class="sdx-card-top">' +
      '<div class="sdx-ico">' + svg(card.icon) + '</div>' +
      '<div class="sdx-name">' + esc(card.title) + '<span>' + esc(card.sub || card.dt) + '</span></div>' +
      '<div class="sdx-tot">\u00b7\u00b7</div>' +
    '</div>' +
    '<div class="sdx-stack"></div>' +
    '<div class="sdx-rows"><div class="sdx-skel"><i></i><i></i><i></i></div></div>';
  container.appendChild(el);
  el.querySelector('.sdx-tot').addEventListener('click', function() { frappe.set_route('List', card.dt); });
  return el;
}

function paint_rows(el, card, rows) {
  const holder = el.querySelector('.sdx-rows');
  const stack  = el.querySelector('.sdx-stack');

  if (!rows.length) {
    holder.innerHTML = '<div class="sdx-empty">No options defined yet</div>';
    stack.classList.add('is-empty');
  } else {
    holder.innerHTML = rows.map(function(r) {
      return '<div class="sdx-row t-' + tone_for(r.label) + '">' +
             '<span class="sdx-dot"></span>' +
             '<span class="sdx-lbl">' + esc(r.label) + '</span>' +
             '<span class="sdx-val">\u00b7\u00b7</span></div>';
    }).join('');

    const rowEls = holder.querySelectorAll('.sdx-row');
    rows.forEach(function(r, i) {
      rowEls[i].addEventListener('click', function() { frappe.set_route('List', card.dt, r.f); });
    });

    Promise.all(rows.map(function(r) { return count(card.dt, r.f); })).then(function(vals) {
      const sum = vals.reduce(function(a, b) { return a + b; }, 0);
      vals.forEach(function(v, i) {
        rowEls[i].querySelector('.sdx-val').textContent = v;
        if (!v) { rowEls[i].classList.add('is-zero'); }
      });
      if (!sum) { stack.classList.add('is-empty'); return; }
      stack.innerHTML = vals.map(function(v, i) {
        if (!v) { return ''; }
        return '<i class="t-' + tone_for(rows[i].label) + '" style="flex:' + v + '" title="' + esc(rows[i].label) + ': ' + v + '"></i>';
      }).join('');
    });
  }

  count(card.dt).then(function(v) { el.querySelector('.sdx-tot').textContent = v; });
}

// ---- Wide card: proportional bars ------------------------------------
function paint_wide() {
  wide.innerHTML = '';
  const el = document.createElement('div');
  el.className = 'sdx-card sdx-wide-card';
  el.style.setProperty('--accent', WIDE.color);
  el.innerHTML =
    '<div class="sdx-card-top">' +
      '<div class="sdx-ico">' + svg(WIDE.icon) + '</div>' +
      '<div class="sdx-name">' + esc(WIDE.title) + '<span>' + esc(WIDE.sub) + '</span></div>' +
      '<div class="sdx-tot">\u00b7\u00b7</div>' +
    '</div><div class="sdx-bars"><div class="sdx-skel"><i></i><i></i><i></i></div></div>';
  wide.appendChild(el);
  el.querySelector('.sdx-tot').addEventListener('click', function() { frappe.set_route('List', WIDE.dt); });

  const bars = el.querySelector('.sdx-bars');
  count(WIDE.dt).then(function(v) { el.querySelector('.sdx-tot').textContent = v; });

  link_options(WIDE.master).then(function(opts) {
    if (!opts.length) { bars.innerHTML = '<div class="sdx-empty">No priorities defined yet</div>'; return; }
    bars.innerHTML = opts.map(function(o) {
      return '<div class="sdx-barrow t-' + tone_for(o) + '">' +
             '<span class="sdx-barlbl">' + esc(o) + '</span>' +
             '<span class="sdx-track"><i style="width:0%"></i></span>' +
             '<span class="sdx-barval">\u00b7\u00b7</span></div>';
    }).join('');
    const rowEls = bars.querySelectorAll('.sdx-barrow');
    opts.forEach(function(o, i) {
      var f = {}; f[WIDE.field] = o;
      rowEls[i].addEventListener('click', function() { frappe.set_route('List', WIDE.dt, f); });
    });
    Promise.all(opts.map(function(o) {
      var f = {}; f[WIDE.field] = o; return count(WIDE.dt, f);
    })).then(function(vals) {
      const max = Math.max.apply(null, vals.concat([1]));
      vals.forEach(function(v, i) {
        rowEls[i].querySelector('.sdx-barval').textContent = v;
        rowEls[i].querySelector('.sdx-track i').style.width = Math.round((v / max) * 100) + '%';
        if (!v) { rowEls[i].classList.add('is-zero'); }
      });
    });
  });
}

// ---- Build ------------------------------------------------------------
function render() {
  kpiBox.innerHTML = '';
  grid.innerHTML = '';
  wide.innerHTML = '';

  paint_kpis();

  FIXED.forEach(function(card) {
    paint_rows(shell(card, grid), card, card.rows);
  });

  AUTO.forEach(function(card) {
    const el = shell(card, grid);
    status_options(card.dt, card.field).then(function(opts) {
      paint_rows(el, card, to_rows(card.field, opts));
    });
  });

  LINKED.forEach(function(card) {
    const el = shell(card, grid);
    link_options(card.master).then(function(opts) {
      paint_rows(el, card, to_rows(card.field, opts));
    });
  });

  paint_wide();
}

root_element.querySelector('.sdx-refresh').addEventListener('click', function() {
  const b = this;
  b.classList.add('is-spinning');
  render();
  setTimeout(function() { b.classList.remove('is-spinning'); }, 700);
});

render();

style:
.sdx { padding: 2px 0 10px; --good: #16a34a; --warn: #ea580c; --info: #2563eb; --bad: #dc2626; --idle: #94a3b8; }
.sdx .t-good { --tone: var(--good); --tint: rgba(22,163,74,.12); }
.sdx .t-warn { --tone: var(--warn); --tint: rgba(234,88,12,.12); }
.sdx .t-info { --tone: var(--info); --tint: rgba(37,99,235,.12); }
.sdx .t-bad  { --tone: var(--bad);  --tint: rgba(220,38,38,.12); }
.sdx .t-idle { --tone: var(--idle); --tint: rgba(148,163,184,.14); }

/* header */
.sdx-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 16px; margin-bottom: 20px; }
.sdx-h1 { font-size: 24px; font-weight: 650; letter-spacing: -0.02em; line-height: 1.15; }
.sdx-h2 { font-size: 12.5px; color: var(--text-muted, #6b7280); margin-top: 4px; }
.sdx-refresh { display: inline-flex; align-items: center; gap: 7px; border: 1px solid var(--border-color, #e5e7eb); background: var(--card-bg, #fff); color: var(--text-muted, #6b7280); border-radius: 8px; padding: 7px 12px; font-size: 12.5px; font-weight: 500; cursor: pointer; transition: all .15s ease; flex: none; }
.sdx-refresh:hover { color: var(--text-color, #111827); border-color: var(--text-muted, #9ca3af); }
.sdx-refresh svg { width: 14px; height: 14px; }
.sdx-refresh.is-spinning svg { animation: sdx-spin .7s linear; }
@keyframes sdx-spin { to { transform: rotate(360deg); } }

/* KPI strip */
.sdx-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(190px, 1fr)); gap: 12px; margin-bottom: 16px; }
.sdx-kpi { display: flex; align-items: center; gap: 13px; padding: 15px 16px; border-radius: 13px; background: var(--tint); border: 1px solid transparent; cursor: pointer; transition: transform .14s ease, box-shadow .14s ease; }
.sdx-kpi:hover { transform: translateY(-2px); box-shadow: 0 6px 18px -8px rgba(0,0,0,.28); }
.sdx-kpi-ico { width: 38px; height: 38px; border-radius: 10px; display: grid; place-items: center; background: var(--card-bg, #fff); color: var(--tone); flex: none; }
.sdx-kpi-ico svg { width: 19px; height: 19px; }
.sdx-kpi-val { font-size: 25px; font-weight: 700; line-height: 1.05; color: var(--tone); font-variant-numeric: tabular-nums; }
.sdx-kpi-lbl { font-size: 11.5px; font-weight: 500; color: var(--text-muted, #6b7280); margin-top: 2px; }
.sdx-kpi.is-zero { opacity: .62; }

/* card grid */
.sdx-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(268px, 1fr)); gap: 14px; }
.sdx-card { background: var(--card-bg, #fff); border: 1px solid var(--border-color, #e5e7eb); border-radius: 14px; padding: 15px 16px 13px; display: flex; flex-direction: column; transition: box-shadow .16s ease, border-color .16s ease; }
.sdx-card:hover { box-shadow: 0 8px 24px -14px rgba(0,0,0,.32); border-color: var(--accent); }

.sdx-card-top { display: flex; align-items: center; gap: 10px; }
.sdx-ico { width: 30px; height: 30px; border-radius: 9px; display: grid; place-items: center; color: var(--accent); background: var(--accent); flex: none; }
.sdx-ico svg { width: 16px; height: 16px; color: var(--card-bg, #fff); }
.sdx-name { flex: 1; min-width: 0; font-size: 13.5px; font-weight: 600; line-height: 1.25; color: var(--text-color, #111827); }
.sdx-name span { display: block; font-size: 10.5px; font-weight: 500; color: var(--text-muted, #9ca3af); letter-spacing: .02em; margin-top: 1px; }
.sdx-tot { font-size: 22px; font-weight: 700; color: var(--accent); font-variant-numeric: tabular-nums; cursor: pointer; line-height: 1; }

/* distribution stack */
.sdx-stack { display: flex; gap: 2px; height: 5px; border-radius: 99px; overflow: hidden; margin: 13px 0 11px; background: var(--fg-hover-color, #f1f2f4); }
.sdx-stack i { background: var(--tone); border-radius: 99px; min-width: 3px; }
.sdx-stack.is-empty { opacity: .45; }

/* rows */
.sdx-rows { flex: 1; }
.sdx-row { display: flex; align-items: center; gap: 9px; padding: 6px 7px; margin: 0 -7px; font-size: 12.8px; cursor: pointer; border-radius: 7px; transition: background .12s ease; }
.sdx-row:hover { background: var(--fg-hover-color, #f3f4f6); }
.sdx-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--tone); flex: none; box-shadow: 0 0 0 3px var(--tint); }
.sdx-lbl { color: var(--text-color, #374151); flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.sdx-val { font-weight: 650; font-variant-numeric: tabular-nums; color: var(--text-color, #111827); }
.sdx-row.is-zero { opacity: .45; }
.sdx-empty { font-size: 12px; color: var(--text-muted, #9ca3af); padding: 8px 0; }

/* loading skeleton */
.sdx-skel i { display: block; height: 9px; border-radius: 5px; margin: 9px 0; background: var(--fg-hover-color, #eef0f2); animation: sdx-pulse 1.2s ease-in-out infinite; }
.sdx-skel i:nth-child(2) { width: 78%; animation-delay: .12s; }
.sdx-skel i:nth-child(3) { width: 55%; animation-delay: .24s; }
@keyframes sdx-pulse { 0%,100% { opacity: 1; } 50% { opacity: .45; } }

/* wide card */
.sdx-wide { margin-top: 14px; }
.sdx-bars { margin-top: 15px; display: grid; gap: 11px; }
.sdx-barrow { display: grid; grid-template-columns: 120px 1fr 46px; align-items: center; gap: 12px; cursor: pointer; padding: 3px 6px; margin: 0 -6px; border-radius: 7px; transition: background .12s ease; }
.sdx-barrow:hover { background: var(--fg-hover-color, #f3f4f6); }
.sdx-barlbl { font-size: 12.8px; font-weight: 550; color: var(--text-color, #374151); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.sdx-track { height: 9px; border-radius: 99px; background: var(--fg-hover-color, #f1f2f4); overflow: hidden; }
.sdx-track i { display: block; height: 100%; border-radius: 99px; background: var(--tone); transition: width .45s cubic-bezier(.4,0,.2,1); }
.sdx-barval { font-size: 14px; font-weight: 700; text-align: right; font-variant-numeric: tabular-nums; color: var(--tone); }
.sdx-barrow.is-zero { opacity: .45; }

@media (max-width: 560px) {
  .sdx-barrow { grid-template-columns: 92px 1fr 38px; gap: 9px; }
  .sdx-h1 { font-size: 21px; }
}

script:
/* ===== Customer Progress (Interio layout, built on TBH Energy's own pipeline) ===== */
(function () {
    // Each stage: doctype, which field holds the customer, and the rule for "Completed".
    // A record that exists but is not yet completed shows as "In Progress"; no record = "Pending".
    const STAGES = [
        { title: "Site Visit", doctype: "Site Visit", status_field: "status", done: ["Approved"] },
        { title: "Quotation", doctype: "Quotation", cust: "party_name", extra: { quotation_to: "Customer" }, status_field: "status", done: ["Ordered"], fields: ["grand_total"] },
        { title: "Loan", doctype: "Solar Loan", status_field: "status", done: ["Approved"], optional: true },
        { title: "Sales Order", doctype: "Sales Order", submitted: true },
        { title: "Project", doctype: "Project", status_field: "status", done: ["Completed"] },
        { title: "Product Delivery", doctype: "Product Delivery", status_field: "transfer_status", done: ["Transferred"] },
        { title: "Installation", doctype: "Installation", status_field: "installation_status", done: ["Completed"] },
        { title: "Paper Work", doctype: "Paper Work", status_field: "status", done: ["Completed"], fields: ["custom_consumer_no"] },
        { title: "KSEB", doctype: "KSEB Paper Works", status_field: "status_of_kseb_paper_work", done: ["Completed"], fields: ["capacity_kw"] },
        { title: "Subsidy", doctype: "Subsidy", status_field: "status", done: ["Sanctioned"], fields: ["capacity_kw"] },
        { title: "Project Commission", doctype: "Project Commission", status_field: "status_of_project_commission", done: ["Commissioned"] },
        { title: "Sales Invoice", doctype: "Sales Invoice", status_field: "status", done: ["Paid"], fields: ["grand_total"] }
    ];
    const N = STAGES.length;
    const IDX = (dt) => STAGES.findIndex((s) => s.doctype === dt);
    const SV = IDX("Site Visit"), QT = IDX("Quotation"), LOAN = IDX("Solar Loan"), PW = IDX("Paper Work"), KS = IDX("KSEB Paper Works"), SUB = IDX("Subsidy");
    const SV_FIELDS = ["custom_location_name", "location_site_address", "property_type", "phone"];
    const BIG = 100000;
    const PILL = { done: "Completed", prog: "In Progress", pend: "Pending", na: "No Loan" };

    const q = (s) => root_element.querySelector(s);
    const list = q("[data-list]"), statusSel = q("[data-status]"), search = q("[data-search]"), pager = q("[data-pager]"), cardsBox = q("[data-cards]");
    const chartBox = q("[data-chart]"), chartScroll = q("[data-chart-scroll]"), chartSub = q("[data-chart-sub]"), reloadBtn = q("[data-reload]");
    const esc = (v) => frappe.utils.escape_html(v == null ? "" : String(v));
    const fdate = (d) => { if (!d) return "—"; try { return frappe.datetime.str_to_user(String(d).slice(0, 10)); } catch (e) { return d; } };
    const money = (v) => { if (v === null || v === undefined || v === "") return "—"; try { return typeof format_currency === "function" ? format_currency(v) : String(v); } catch (e) { return String(v); } };
    let pageSize = 20, loadSeq = 0, cards = [], timer = null;

    STAGES.forEach((s) => statusSel.insertAdjacentHTML("beforeend", `<option value="${esc(s.title)}">${esc(s.title)}</option>`));
    statusSel.querySelector('option[value=""]').insertAdjacentHTML("afterend", `<option value="__none">Not Started</option><option value="__done">All Completed</option>`);

    const stage_fields = (s) => {
        let f = [];
        if (s.status_field) f.push(s.status_field);
        if (s.submitted) f.push("docstatus");
        if (s.fields) f = f.concat(s.fields);
        return f;
    };

    // Latest non-cancelled record per customer for one doctype
    async function latest(s, extraFields, names) {
        const cf = s.cust || "customer";
        const filters = Object.assign({ docstatus: ["!=", 2] }, s.extra || {});
        filters[cf] = ["in", names];
        const fields = [...new Set(["name", "creation", "modified", cf].concat(stage_fields(s), extraFields || []))];
        try {
            const rows = await frappe.db.get_list(s.doctype, { filters, fields, order_by: "creation desc", limit: BIG });
            const out = {};
            (rows || []).forEach((r) => { const c = r[cf]; if (c && !out[c]) out[c] = r; });
            return out;
        } catch (e) { return {}; }
    }

    function is_done(s, r) {
        if (s.submitted) return Number(r.docstatus) === 1;
        return (s.done || []).map((d) => d.toLowerCase()).includes(String(r[s.status_field] || "").trim().toLowerCase());
    }

    // Loan is optional: once a customer has a Sales Order without any loan, the Loan stage is "No Loan"
    const SO = IDX("Sales Order");
    function stage_state(i, maps, cust) {
        const s = STAGES[i], r = maps[i] ? maps[i][cust] : null;
        if (!r) {
            if (s.optional && maps[SO] && maps[SO][cust]) return { stage: s, rec: null, state: "na" };
            return { stage: s, rec: null, state: "pend" };
        }
        return { stage: s, rec: r, state: is_done(s, r) ? "done" : "prog" };
    }
    const finished = (steps) => steps.every((st) => st.state === "done" || st.state === "na");

    /* ---- Stage chart over ALL customers ---- */
    const set_chip = (key, v) => { const el = cardsBox.querySelector(`[data-count="${key}"] strong`); if (el) el.textContent = v; };
    cardsBox.addEventListener("click", (e) => {
        const b = e.target.closest("[data-count]"); if (!b) return;
        if (b.dataset.count === "loan") frappe.set_route("List", "Solar Loan");
        else frappe.set_route("List", "Customer");
    });

    let stats = null, statSeq = 0;
    async function load_stats() {
        const mine = ++statSeq;
        if (!stats) chartBox.innerHTML = `<div class="sd2-chart-msg">Counting customers at each stage…</div>`;
        try {
            const all = await frappe.db.get_list("Customer", { fields: ["name"], filters: { disabled: 0 }, limit: BIG });
            if (mine !== statSeq) return;
            const names = all.map((c) => c.name);
            set_chip("total", String(names.length));
            if (!names.length) {
                stats = null; ["loan", "noloan", "pending", "completed"].forEach((k) => set_chip(k, "0"));
                chartSub.textContent = "No customers yet."; chartBox.innerHTML = `<div class="sd2-chart-msg">No customers yet.</div>`; return;
            }
            const maps = await Promise.all(STAGES.map((s) => latest(s, [], names)));
            if (mine !== statSeq) return;
            const loanN = names.filter((n) => maps[LOAN][n]).length;
            set_chip("loan", String(loanN));
            set_chip("noloan", String(names.length - loanN));
            let doneN = 0;
            const per = names.map((n) => STAGES.map((_, i) => stage_state(i, maps, n)));
            per.forEach((steps) => { if (finished(steps)) doneN++; });
            set_chip("completed", String(doneN));
            set_chip("pending", String(names.length - doneN));
            const rows = STAGES.map((s, i) => {
                let done = 0, prog = 0, na = 0;
                per.forEach((steps) => { const st = steps[i].state; if (st === "done") done++; else if (st === "prog") prog++; else if (st === "na") na++; });
                return { stage: s, done, prog, na, pending: names.length - done - prog - na };
            });
            stats = { total: names.length, rows };
            chartSub.textContent = `Customers at each of the ${N} stages — based on all ${names.length} active customers.`;
            render_chart();
        } catch (e) {
            if (mine === statSeq) chartBox.innerHTML = `<div class="sd2-chart-msg">Stage counts could not be loaded. Use the reload button to try again.</div>`;
        }
    }

    function nice_step(x) {
        if (x <= 1) return 1;
        const p = Math.pow(10, Math.floor(Math.log10(x))), n = x / p;
        return (n <= 1 ? 1 : n <= 2 ? 2 : n <= 5 ? 5 : 10) * p;
    }
    function wrap_label(text, maxChars) {
        const words = text.split(" "), lines = [""];
        words.forEach((w) => {
            const cur = lines[lines.length - 1];
            if (!cur) lines[lines.length - 1] = w;
            else if ((cur + " " + w).length <= maxChars) lines[lines.length - 1] = cur + " " + w;
            else lines.push(w);
        });
        if (lines.length > 2) { lines[1] = lines.slice(1).join(" "); lines.length = 2; }
        return lines.map((l) => (l.length > maxChars + 2 ? l.slice(0, maxChars + 1) + "…" : l));
    }

    function render_chart() {
        if (!stats) return;
        const cw = Math.max(960, Math.floor(chartScroll.clientWidth || 960));
        const H = 320, pl = 40, pr = 12, pt = 26, pb = 58;
        const pw = cw - pl - pr, ph = H - pt - pb, gw = pw / N;
        const gap = Math.max(2, Math.min(6, gw * 0.06));
        const step = nice_step(Math.max(1, stats.total) / 4);
        const top = Math.max(step, Math.ceil(Math.max(1, stats.total) / step) * step);
        const y = (v) => pt + ph - (v / top) * ph;
        const maxChars = Math.max(8, Math.floor(gw / 6.3));

        let s = `<svg width="${cw}" height="${H}" viewBox="0 0 ${cw} ${H}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Customers at each work stage">`;
        for (let t = 0; t <= top + 0.0001; t += step) {
            s += `<line class="sd2-grid" x1="${pl}" x2="${cw - pr}" y1="${y(t)}" y2="${y(t)}"/>`;
            s += `<text class="sd2-axis" x="${pl - 8}" y="${y(t) + 3.5}" text-anchor="end">${t}</text>`;
        }
        stats.rows.forEach((r, i) => {
            const gx = pl + gw * i, cx = gx + gw / 2;
            const series = [{ v: r.pending, k: "pend" }, { v: r.prog, k: "prog" }, { v: r.done, k: "done" }];
            if (r.stage.optional) series.push({ v: r.na, k: "na" });
            const bw = Math.max(8, Math.min(22, (gw * 0.7 - gap * (series.length - 1)) / series.length));
            const x0 = cx - (series.length * bw + (series.length - 1) * gap) / 2;
            const tip = `${i + 1}. ${r.stage.title} — Pending ${r.pending}, In Progress ${r.prog}, Completed ${r.done}` + (r.stage.optional ? `, No Loan ${r.na}` : "") + " (click to open)";
            s += `<g class="sd2-grp" data-g="${i}" tabindex="0" role="button" aria-label="${esc(tip)}"><title>${esc(tip)}</title>`;
            s += `<rect class="sd2-hit" x="${gx + 2}" y="${pt - 18}" width="${gw - 4}" height="${ph + pb + 16}" rx="6"/>`;
            series.forEach((b, k) => {
                const x = x0 + k * (bw + gap), h = (b.v / top) * ph;
                if (h > 0) s += `<rect class="sd2-bar-${b.k}" x="${x}" y="${y(b.v)}" width="${bw}" height="${h}" rx="3"/>`;
                s += `<text class="sd2-val sd2-val-${b.k}" x="${x + bw / 2}" y="${y(b.v) - 5}" text-anchor="middle">${b.v}</text>`;
            });
            const lines = wrap_label(`${i + 1}. ${r.stage.title}`, maxChars);
            s += `<text class="sd2-xl" x="${cx}" y="${pt + ph + 18}" text-anchor="middle">` + lines.map((l, k) => `<tspan x="${cx}" dy="${k ? 13 : 0}">${esc(l)}</tspan>`).join("") + `</text></g>`;
        });
        s += `<line class="sd2-base" x1="${pl}" x2="${cw - pr}" y1="${pt + ph}" y2="${pt + ph}"/></svg>`;
        chartBox.innerHTML = s;
    }
    const open_stage_list = (i) => { const st = STAGES[i]; if (st) frappe.set_route("List", st.doctype); };
    chartBox.addEventListener("click", (e) => { const g = e.target.closest("[data-g]"); if (g) open_stage_list(+g.dataset.g); });
    chartBox.addEventListener("keydown", (e) => {
        const g = e.target.closest && e.target.closest("[data-g]");
        if (g && (e.key === "Enter" || e.key === " ")) { e.preventDefault(); e.stopPropagation(); open_stage_list(+g.dataset.g); }
    });
    if (window.ResizeObserver) {
        let rt = null, lastW = 0;
        new ResizeObserver(() => {
            const w = chartScroll.clientWidth;
            if (w === lastW) return;
            lastW = w; clearTimeout(rt); rt = setTimeout(render_chart, 120);
        }).observe(chartScroll);
    }

    /* ---- Customer cards ---- */
    async function fetch_customers(term) {
        const fields = ["name", "customer_name", "creation"];
        const base = { disabled: 0 };
        if (!term) return frappe.db.get_list("Customer", { fields, filters: base, order_by: "creation desc", limit: pageSize });
        const like = `%${term}%`;
        const [a, b] = await Promise.all([
            frappe.db.get_list("Customer", { fields: ["name"], filters: [["customer_name", "like", like]], limit: pageSize }).catch(() => []),
            frappe.db.get_list("Paper Work", { fields: ["customer"], filters: [["custom_consumer_no", "like", like]], limit: pageSize }).catch(() => [])
        ]);
        const ids = [...new Set(a.map((x) => x.name).concat(b.map((x) => x.customer).filter(Boolean)))].slice(0, pageSize);
        if (!ids.length) return [];
        return frappe.db.get_list("Customer", { fields, filters: { name: ["in", ids] }, order_by: "creation desc", limit: ids.length });
    }

    async function load() {
        const seq = ++loadSeq;
        list.innerHTML = `<div class="sd2-empty">Loading customers…</div>`;
        let customers;
        try { customers = await fetch_customers(search.value.trim()); }
        catch (e) { if (seq === loadSeq) list.innerHTML = `<div class="sd2-empty">Customers could not be loaded. Check that you have permission to read Customer.</div>`; return; }
        if (seq !== loadSeq) return;
        if (!customers.length) { cards = []; paint(); return; }
        const names = customers.map((c) => c.name);
        const maps = await Promise.all(STAGES.map((s, i) => latest(s, i === SV ? SV_FIELDS : [], names)));
        if (seq !== loadSeq) return;

        cards = customers.map((c) => {
            const steps = STAGES.map((_, i) => stage_state(i, maps, c.name));
            let current = null, latestAt = null;
            steps.forEach((st) => {
                if (!st.rec || !st.rec.modified) return;
                const t = new Date(String(st.rec.modified).replace(" ", "T"));
                if (latestAt === null || t > latestAt) { latestAt = t; current = st; }
            });
            const pick = (i, f) => (maps[i] && maps[i][c.name] ? maps[i][c.name][f] : null);
            const sv = maps[SV][c.name] || {};
            const kw = pick(KS, "capacity_kw") || pick(SUB, "capacity_kw");
            return {
                id: c.name, name: c.customer_name || c.name, sv,
                consumer: pick(PW, "custom_consumer_no"),
                location: sv.custom_location_name || sv.location_site_address,
                type: sv.property_type, phone: sv.phone,
                capacity: kw ? `${kw} kW` : "",
                quotation: pick(QT, "grand_total"),
                submitted: c.creation,
                steps, current, allDone: finished(steps)
            };
        });
        paint();
    }

    function badge(card) {
        if (card.allDone) return `<span class="sd2-badge tone-done">Completed</span>`;
        if (!card.current) return `<span class="sd2-badge tone-idle">Not Started</span>`;
        const tone = card.current.state === "done" ? "done" : "prog";
        return `<span class="sd2-badge tone-${tone}" title="${esc(card.current.stage.title)}">${esc(card.current.stage.title)}</span>`;
    }
    const cell = (label, value, cls) => `<div class="sd2-cell"><span class="sd2-k">${label}</span><span class="sd2-v${cls ? " " + cls : ""}">${value}</span></div>`;

    function card_html(card, idx) {
        const steps = card.steps.map((st, i) => `
            <li class="sd2-step st-${st.state}" data-card="${idx}" data-step="${i}" role="button" tabindex="0" title="${esc(st.state === "na" ? st.stage.title + ": no loan for this customer" : "Open " + st.stage.title)}">
                <span class="sd2-num">${i + 1}</span>
                <span class="sd2-label">${esc(st.stage.title)}</span>
                <span class="sd2-pill">${PILL[st.state]}</span>
                ${st.rec ? `<span class="sd2-date">${fdate(st.rec.creation)}</span>` : ""}
            </li>`).join("");
        return `
            <div class="sd2-card">
                <div class="sd2-info" data-open="${idx}" title="Open ${esc(card.name)}">
                    ${cell("Customer Name", esc(card.name), "sd2-name sd2-clip")}
                    ${cell("Consumer Number", esc(card.consumer || "—"))}
                    ${cell("Place / Location", esc(card.location || "—"), "sd2-clip")}
                    ${cell("Capacity", esc(card.capacity || "—"), "sd2-clip")}
                    ${cell("Project Type", esc(card.type || "—"))}
                    ${cell("Mobile No.", esc(card.phone || "—"))}
                    ${cell("Quotation Amount", esc(money(card.quotation)))}
                    ${cell("Work Stage Status", badge(card))}
                    ${cell("Submitted Date", fdate(card.submitted))}
                    <div class="sd2-more">
                        <button type="button" class="sd2-dots" data-menu="${idx}" aria-label="More actions for ${esc(card.name)}" aria-haspopup="true">•••</button>
                        <div class="sd2-menu" data-menu-list="${idx}" hidden>
                            <button type="button" data-act="cust" data-i="${idx}">Open customer</button>
                            ${card.sv && card.sv.name ? `<button type="button" data-act="visit" data-i="${idx}">Open site visit</button>` : ""}
                        </div>
                    </div>
                </div>
                <ol class="sd2-rail">${steps}</ol>
            </div>`;
    }

    function paint() {
        const want = statusSel.value;
        const shown = cards.map((c, i) => ({ c, i })).filter(({ c }) =>
            !want ? true
            : want === "__none" ? !c.current
            : want === "__done" ? c.allDone
            : (!c.allDone && c.current && c.current.stage.title === want));
        if (!cards.length) {
            list.innerHTML = `<div class="sd2-empty">${search.value.trim() ? `No customer or consumer number matches “${esc(search.value.trim())}”.` : "No customers yet."}</div>`;
            return;
        }
        if (!shown.length) { list.innerHTML = `<div class="sd2-empty">No customers are at “${esc(statusSel.options[statusSel.selectedIndex].text)}” right now.</div>`; return; }
        list.innerHTML = shown.map(({ c, i }) => card_html(c, i)).join("");
    }

    function open_step(card, st) {
        if (st.rec) return frappe.set_route("Form", st.stage.doctype, st.rec.name);
        const f = {}; f[st.stage.cust || "customer"] = card.id;
        return frappe.set_route("List", st.stage.doctype, f);
    }
    const closeMenus = () => list.querySelectorAll(".sd2-menu").forEach((m) => (m.hidden = true));

    list.addEventListener("click", (e) => {
        const dots = e.target.closest("[data-menu]");
        if (dots) {
            e.stopPropagation();
            const menu = list.querySelector(`[data-menu-list="${dots.dataset.menu}"]`);
            const was = menu.hidden; closeMenus(); menu.hidden = !was; return;
        }
        const act = e.target.closest("[data-act]");
        if (act) {
            const card = cards[+act.dataset.i]; closeMenus();
            if (act.dataset.act === "visit" && card.sv && card.sv.name) frappe.set_route("Form", "Site Visit", card.sv.name);
            else frappe.set_route("Form", "Customer", card.id);
            return;
        }
        if (e.target.closest(".sd2-menu")) return;
        const step = e.target.closest("[data-step]");
        if (step) { const card = cards[+step.dataset.card]; return open_step(card, card.steps[+step.dataset.step]); }
        const info = e.target.closest("[data-open]");
        if (info) frappe.set_route("Form", "Customer", cards[+info.dataset.open].id);
    });
    list.addEventListener("keydown", (e) => {
        const step = e.target.closest && e.target.closest("[data-step]");
        if (step && (e.key === "Enter" || e.key === " ")) { e.preventDefault(); e.stopPropagation(); const card = cards[+step.dataset.card]; open_step(card, card.steps[+step.dataset.step]); }
    });
    root_element.addEventListener("click", (e) => { if (!e.target.closest(".sd2-more")) closeMenus(); });

    statusSel.addEventListener("change", paint);
    search.addEventListener("input", () => { clearTimeout(timer); timer = setTimeout(load, 300); });
    ["keydown", "keyup", "keypress"].forEach((ev) => search.addEventListener(ev, (e) => e.stopPropagation()));
    pager.addEventListener("click", (e) => {
        const b = e.target.closest("[data-n]"); if (!b) return;
        pageSize = +b.dataset.n;
        pager.querySelectorAll("[data-n]").forEach((x) => x.classList.toggle("on", x === b));
        load();
    });
    if (reloadBtn) {
        reloadBtn.addEventListener("click", async () => {
            if (reloadBtn.disabled) return;
            reloadBtn.disabled = true; reloadBtn.classList.add("sd2-spin");
            try { await Promise.all([load_stats(), load()]); }
            finally { reloadBtn.disabled = false; reloadBtn.classList.remove("sd2-spin"); }
        });
    }

    load_stats();
    load();
})();

style:
:host { display: block; }
.sd2 { color: var(--text-color, #111827); padding: 12px 0 16px; width: 100%; border-top: 1px solid var(--border-color, #e5e7eb); margin-top: 8px; }
.sd2 * { box-sizing: border-box; }
.sd2-top { display: flex; justify-content: space-between; align-items: flex-end; gap: 16px; flex-wrap: wrap; margin: 16px 0; }
.sd2-title { font-size: 21px; font-weight: 600; letter-spacing: -0.01em; margin: 0; color: var(--heading-color, var(--text-color, #111827)); }
.sd2-sub { margin: 4px 0 0; font-size: 12px; color: var(--text-muted, #6b7280); }
.sd2-tools { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; }
.sd2-status, .sd2-btn { height: 34px; border: 1px solid var(--border-color, #e5e7eb); border-radius: var(--border-radius, 6px); background: var(--card-bg, #fff); font: inherit; font-size: 13px; color: var(--text-color, #111827); cursor: pointer; }
.sd2-status { min-width: 150px; padding: 0 28px 0 12px; }
.sd2-btn { padding: 0 14px; white-space: nowrap; }
.sd2-btn:hover { background: var(--subtle-fg, #f3f4f6); }
.sd2-icon { width: 34px; padding: 0; display: inline-grid; place-items: center; }
.sd2-icon[disabled] { cursor: progress; opacity: .75; }
.sd2-spin .sd2-reload-ico { animation: sd2-spin .8s linear infinite; }
@keyframes sd2-spin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) { .sd2-spin .sd2-reload-ico { animation: none; } }
.sd2-search { display: flex; align-items: center; gap: 8px; height: 34px; width: 340px; max-width: 100%; padding: 0 12px; border: 1px solid var(--border-color, #e5e7eb); border-radius: var(--border-radius, 6px); background: var(--card-bg, #fff); color: var(--text-muted, #6b7280); }
.sd2-search input { border: 0; outline: 0; flex: 1; min-width: 0; font: inherit; font-size: 13px; color: var(--text-color, #111827); background: transparent; }
.sd2-status:focus-visible, .sd2-btn:focus-visible, .sd2-search:focus-within { outline: 2px solid #2563eb; outline-offset: 1px; }

.sd2-panel { border: 1px solid var(--border-color, #e5e7eb); border-radius: 12px; background: var(--card-bg, #fff); padding: 16px 18px 10px; margin-bottom: 18px; }
.sd2-panel-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 16px; flex-wrap: wrap; }
.sd2-panel-title { margin: 0; font-size: 15px; font-weight: 600; color: var(--heading-color, var(--text-color, #111827)); }
.sd2-panel-sub { margin: 4px 0 0; font-size: 12px; color: var(--text-muted, #6b7280); }
.sd2-chips { display: flex; gap: 8px; flex-wrap: wrap; }
.sd2-chip { display: inline-flex; align-items: baseline; gap: 8px; padding: 6px 12px; border: 1px solid var(--border-color, #e5e7eb); border-radius: 999px; background: var(--card-bg, #fff); font: inherit; font-size: 12px; color: var(--text-muted, #4b5563); cursor: pointer; }
.sd2-chip strong { font-size: 14px; font-weight: 600; color: var(--heading-color, var(--text-color, #111827)); }
.sd2-chip:hover { background: var(--subtle-fg, #f3f4f6); }
.sd2-chip:focus-visible { outline: 2px solid #2563eb; outline-offset: 1px; }
.sd2-legend { display: flex; gap: 18px; flex-wrap: wrap; margin: 12px 0 2px; font-size: 12px; color: var(--text-color, #374151); }
.sd2-legend span { display: inline-flex; align-items: center; gap: 6px; }
.sd2-sw { width: 12px; height: 12px; border-radius: 3px; display: inline-block; }
.sd2-sw-pend { background: #94a3b8; }
.sd2-sw-prog { background: #3b82f6; }
.sd2-sw-done { background: #16a34a; }
.sd2-sw-na { background: #ec4899; }
.sd2-chart-scroll { overflow-x: auto; }
.sd2-chart svg { display: block; }
.sd2-chart-msg { padding: 60px 20px; text-align: center; font-size: 13px; color: var(--text-muted, #6b7280); }
.sd2-grid { stroke: var(--border-color, #eef0f3); stroke-width: 1; }
.sd2-base { stroke: var(--gray-400, #cbd5e1); stroke-width: 1; }
.sd2-axis { font-size: 10px; fill: var(--text-muted, #6b7280); }
.sd2-xl { font-size: 11px; fill: var(--text-color, #374151); }
.sd2-val { font-size: 10.5px; font-weight: 600; }
.sd2-val-pend { fill: #64748b; }
.sd2-val-prog { fill: #1d4ed8; }
.sd2-val-done { fill: #15803d; }
.sd2-val-na { fill: #be185d; }
.sd2-bar-pend { fill: #94a3b8; }
.sd2-bar-prog { fill: #3b82f6; }
.sd2-bar-done { fill: #16a34a; }
.sd2-bar-na { fill: #ec4899; }
.sd2-hit { fill: transparent; }
.sd2-grp { cursor: pointer; outline: none; }
.sd2-grp:hover .sd2-hit { fill: var(--subtle-fg, #f3f4f6); }
.sd2-grp:focus-visible .sd2-hit { fill: var(--subtle-fg, #f3f4f6); stroke: #2563eb; stroke-width: 2; }

.sd2-scroll { overflow-x: auto; padding-bottom: 6px; }
.sd2-list { display: flex; flex-direction: column; gap: 14px; min-width: 1100px; }
.sd2-card { border: 1px solid var(--border-color, #e5e7eb); border-radius: 12px; background: var(--card-bg, #fff); overflow: hidden; }
.sd2-info { display: grid; grid-template-columns: 1.15fr 1.1fr 1.2fr .9fr .9fr 1fr 1fr 1.3fr .95fr 44px; align-items: center; gap: 12px; background: var(--subtle-fg, #f5f7fa); border-bottom: 1px solid var(--border-color, #eef0f3); padding: 12px 16px; cursor: pointer; }
.sd2-info:hover { background: var(--subtle-accent, #eef2f7); }
.sd2-cell { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.sd2-k { font-size: 11px; color: var(--text-muted, #4b5563); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.sd2-v { font-size: 13px; color: var(--text-color, #111827); white-space: nowrap; }
.sd2-name { font-weight: 700; }
.sd2-clip { overflow: hidden; text-overflow: ellipsis; }
.sd2-badge { display: inline-block; width: fit-content; max-width: 100%; overflow: hidden; text-overflow: ellipsis; font-size: 11px; font-weight: 600; padding: 3px 10px; border-radius: 999px; white-space: nowrap; }
.tone-prog { background: #dbeafe; color: #1d4ed8; }
.tone-done { background: #dcfce7; color: #15803d; }
.tone-idle { background: var(--gray-200, #e5e7eb); color: var(--text-color, #374151); }

.sd2-more { position: relative; justify-self: end; }
.sd2-dots { width: 32px; height: 32px; border: 1px solid var(--border-color, #e5e7eb); border-radius: 6px; background: var(--card-bg, #fff); font-size: 10px; letter-spacing: 1px; color: var(--text-color, #374151); cursor: pointer; }
.sd2-dots:hover { background: var(--subtle-fg, #f3f4f6); }
.sd2-menu { position: absolute; right: 0; top: calc(100% + 4px); z-index: 10; min-width: 160px; padding: 4px; background: var(--card-bg, #fff); border: 1px solid var(--border-color, #e5e7eb); border-radius: 8px; box-shadow: 0 8px 24px rgba(17,24,39,.12); }
.sd2-menu button { display: block; width: 100%; text-align: left; padding: 8px 10px; border: 0; background: none; border-radius: 6px; font: inherit; font-size: 13px; color: var(--text-color, #111827); cursor: pointer; }
.sd2-menu button:hover { background: var(--subtle-fg, #f3f4f6); }

.sd2-rail { list-style: none; margin: 0; padding: 16px 8px 14px; display: grid; grid-template-columns: repeat(12, minmax(72px, 1fr)); }
.sd2-step { position: relative; display: flex; flex-direction: column; align-items: center; gap: 5px; text-align: center; cursor: pointer; padding: 0 3px; }
.sd2-step::before { content: ""; position: absolute; top: 11px; left: -50%; width: 100%; height: 2px; background: #9ca3af; }
.sd2-step:first-child::before { display: none; }
.sd2-step.st-done::before { background: #16a34a; }
.sd2-step.st-prog::before { background: #2563eb; }
.sd2-step.st-na::before { background: #f9a8c9; }
.sd2-num { position: relative; z-index: 1; width: 24px; height: 24px; border-radius: 50%; display: grid; place-items: center; font-size: 11px; font-weight: 600; color: #fff; background: #6b7280; }
.st-done .sd2-num { background: #16a34a; }
.st-prog .sd2-num { background: #2563eb; }
.st-na .sd2-num { background: #ec4899; }
.sd2-label { font-size: 11px; color: var(--text-color, #374151); line-height: 1.25; min-height: 28px; }
.st-done .sd2-label { color: #15803d; }
.st-prog .sd2-label { color: #2563eb; }
.st-na .sd2-label { color: #be185d; }
.sd2-pill { font-size: 10px; padding: 2px 8px; border-radius: 999px; background: var(--subtle-fg, #f3f4f6); color: var(--text-muted, #4b5563); border: 1px solid var(--border-color, #e5e7eb); white-space: nowrap; }
.st-done .sd2-pill { background: #dcfce7; color: #15803d; border-color: #dcfce7; }
.st-prog .sd2-pill { background: #dbeafe; color: #1d4ed8; border-color: #dbeafe; }
.st-na .sd2-pill { background: #fce7f3; color: #be185d; border-color: #fce7f3; }
.sd2-date { font-size: 10.5px; color: var(--text-muted, #4b5563); }
.sd2-step:hover .sd2-num { box-shadow: 0 0 0 3px rgba(37,99,235,.18); }
.sd2-step:focus-visible { outline: 2px solid #2563eb; outline-offset: 2px; border-radius: 6px; }

.sd2-empty { padding: 36px; text-align: center; color: var(--text-muted, #6b7280); font-size: 13px; border: 1px dashed var(--border-color, #e5e7eb); border-radius: 8px; background: var(--card-bg, #fff); }
.sd2-pager { display: inline-flex; margin-top: 12px; border-radius: 6px; overflow: hidden; background: var(--subtle-fg, #f3f4f6); }
.sd2-pager button { border: 0; background: transparent; padding: 6px 10px; font: inherit; font-size: 13px; color: var(--text-color, #374151); cursor: pointer; }
.sd2-pager button.on { background: var(--gray-200, #e5e7eb); font-weight: 600; }
.sd2-pager button:focus-visible { outline: 2px solid #2563eb; }

@media (max-width: 768px) {
  .sd2-search { width: 100%; }
  .sd2-tools { width: 100%; }
  .sd2-panel-head { flex-direction: column; }
}
